INSERT INTO `sys_task` VALUES ('504291504043327488', 46, '个人荣誉', '工作业绩突出，个人获得表彰奖励（项目清单见职称文件附件2）', '国家级计25分，省部级计12分，市厅级计6分，校级A级计3分，校级B级计1分', 25, 0, 1, '不包括附件2中的省教育厅和学校的定期奖励（嘉奖和记功）');
INSERT INTO `sys_task` VALUES ('504291504064299008', 46, '日常教学常规', '上学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 0, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299009', 46, '日常教学常规', '下学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 0, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299010', 46, '日常教学常规', '上学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299011', 46, '日常教学常规', '下学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299012', 46, '日常教学常规', '上学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 0, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299013', 46, '日常教学常规', '下学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 0, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299014', 46, '日常教学常规', '承担综合实训课程任务', '承担1个班的第5学期综合实训(课时数需大于256课时)，计15分', 15, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299015', 46, '日常教学常规', '承担毕业设计、岗位实习的指导任务', '指导15个学生的毕业设计、岗位实习，计5分；指导16-20人，计6分；指导21-25人，计7分；以此类推', 10, 0, 0, '为保证质量，原则上，该项不超过10分。毕业设计成绩通过的学生，相关资料需要完备，及时上传。需通过学院、学校毕业设计检查，以及省教育厅的毕业设计抽查。提供指导的学生班级、姓名等信息作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299016', 46, '日常教学常规', '承担技能抽查课程任务', '承担技能抽查课程任务，课时数大于等于80课时（一个班的技能抽查课程总课时），计5分，其他，计3分', 5, 0, 0, '需要按学院要求，完成校级技能抽查，以及省教育厅的技能抽查。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299017', 46, '日常教学常规', '制订主要教学文件：人才培养方案、课程标准、专业技能考核标准与题库', '主持制定人才培养方案计3分，参与制定计1分；主持制定课程标准计2分，修订课程标准计1分；参与修订专业技能考核标准与题库计1分', 8, 0, 1, '本次认定23级人才培养方案的制订工作，其他工作量暂不认定。今后在认定时，以通过专家论证为准。人才培养方案的制定，提供教研室主任签字的认定名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299018', 46, '日常教学常规', '公开课', '承担院级公开课，计2分；承担校级公开课，计3分', 5, 0, 0, '需要按学院要求，将公开课材料上传至网盘。提供公开课照片及简要说明（学期、授课班级等）作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299019', 46, '日常教学常规', '教师出勤', '每学期周三下午的集中学习，满勤计4分，共计8分。每缺勤1次，扣除0.5分', 8, 0, 0, '因私调整学习时间每学期不超过3次，每超过1次，扣除0.5分。提供教学部下发的考勤数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299020', 46, '日常教学常规', '学生评教', '每学期，学生评教排名学院前30%计10分；排名31%-70%计5分', 20, 0, 0, '提供教学部下发的评教数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('504291504064299021', 46, '日常教学常规', '组织院级各类竞赛', '每组织、策划一场学院竞赛活动，计2分', 4, 0, 0, '针对软件学院全体学生开展各类技能竞赛活动，以赛促学，如Web前端开发大赛、信息安全知识竞赛等，需提交竞赛策划、组织实施等方案，报学院同意，组织学生竞赛');
INSERT INTO `sys_task` VALUES ('504291504064299022', 46, '日常教学常规', '任教研室主任', '担任教研室主任，每学期计5分', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('504291504093659136', 46, '教育教学改革', '课程认证', '合格课认证计1分/1门；优质课认证计5分/1门；金课认证计10分/1门', 10, 0, 0, '以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('504291504093659137', 46, '教育教学改革', '职业教育重点项目建设、资源建设、教学团队建设（项目清单见附件4）', '主持：国家级计35分，省部级计25分，市厅级计10分，校级计5分；\n参与：国家级排名1-5名依次计20、18、16、14、12分，其他名次计5分；\n      省部级排名1-3名依次计8、6、4分，其他名次计2分；\n      市厅级排名第1名计5分，其他名次计1分', 35, 0, 1, '省级及以上项目，可连续两年计分，第一年计100%，第二年计60%。以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('504291504093659138', 46, '教育教学改革', '教材建设', '国家级规划教材：主编（排名第1）计20分/本；主编（其他名次）计15分/本；副主编计8分/本；参编计5分/本；\n省级教材：主编（排名第1）计15分/本；主编（其他名次）计10分/本；副主编计7分/本；参编计5分/本；\n其他教材：主编计5分/本；副主编计3分/本；参编计1分/本', 20, 0, 1, '1.国家级教材包括“十四五”职业教育国家规划教材、职业教育国家级优质教材、全国优秀教材奖等。2.省级教材包括省级职业教育优质教材等。3.要求学校为第一主编单位。4.可连续两年计分，第一年计100%，第二年计60%');
INSERT INTO `sys_task` VALUES ('504291504093659139', 46, '教育教学改革', '教学成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计40分，参与第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计30分，参与第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计20分，参与第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分', 40, 0, 1, '获省级及以上教学成果奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准');
INSERT INTO `sys_task` VALUES ('504291504093659140', 46, '教育教学改革', '教师职业能力竞赛', '国家级：一等奖计50分；二等奖计40分；三等奖计30分；\n省级：一等奖计20分；二等奖计15分；三等奖计10分；\n校级：一等奖计8分；二等奖计6分；三等奖计4分；\n院级：所有参与者计2分；', 50, 0, 0, '获省级及以上教师职业能力竞赛获奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准。根据实际备赛情况，每个团队允许提交不超过总人数50%的名额（在备赛团队中又不在获奖名单中的教师），计2分，以团队负责人提交的名单为准');
INSERT INTO `sys_task` VALUES ('504291504093659141', 46, '教育教学改革', '指导学生参加竞赛获奖（奖项清单见附件6）', '国家级：一等奖第1指导老师计35分，其他指导老师计28分；\n二等奖第1指导老师计24分，其他指导老师计20分；\n三等奖第1指导老师计16分，其他指导老师计12分；\n省部级A类：一等奖第1指导老师计15分、其他指导老师计12分；\n二等奖第1指导老师计9分、其他指导老师计7分；\n三等奖第1指导老师计5分、其他指导老师计4分；\n省部级B类：一等奖第1指导老师计12分、其他指导老师计10分；\n二等奖第1指导老师计7分、其他指导老师计5分；\n三等奖第1指导老师计4分、其他指导老师计3分；\n市厅级一等奖第一指导老师计2分，其他指导老师计1分；院级及其他等次奖项计1分；', 35, 0, 1, '该项不累计计分，以最高项计分为准。教师指导学生参加省教育厅、国家教育部主办的职业院校技能大赛，以团队提交的技能竞赛集训方案中指导团队教师名单为依据，每位教师（在备赛团队中又不在获奖名单中的教师）计2分');
INSERT INTO `sys_task` VALUES ('504291504093659142', 46, '教育教学改革', '毕业设计抽查', '全省同类项目排名前3的，专业负责人加10分，指导团队成员加5分（抽查专业负责人及当年团队指导老师由各学院认定、教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('504291504093659143', 46, '教育教学改革', '优秀人才培养方案和新专业合格性评估', '专业人才培养方案获优秀等级或新设专业办学水平合格性评价验收通过的，专业负责人加10分，指导团队成员加5分（当年团队指导老师由各学院认定，教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('504291504118824960', 46, '科学研究与社会服务', '独立或以第一作者（或通信作者）发表本专业学术论文/教研教改论文/思政教育论文', '发表SCI、SSCI、EI源刊论文或论文被《中国科学》《新华文摘》《中国社会科学文摘》全文转载20分/篇；\n发表CSSCI、CSCD核心库来源期刊论文，计12分/篇；\n发表北大核心期刊论文8分/篇；\n一般期刊：本科院校学报2分/篇；\n一般期刊：一般省级期刊1分/篇', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824961', 46, '科学研究与社会服务', '著作和译著', '独著计16分/本，第一作者计12分/本，第二作者计4分/本\n独译计4分/本，合译第一作者3分/本，第二作者计1分/本', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824962', 46, '科学研究与社会服务', '原创作品、产品', '1.美术类和表演类作品或工艺类作品获奖（参加市厅级及以上政府主管部门主办的各类展览、竞赛并获得表彰奖励，级别以证书盖章或主办部门公章为准）。\n1）国家级：金奖（特等奖、一等奖）计 30 分，银奖（二等奖）计 20 分，铜奖（三等奖）计 10 分；\n2）省部级：金奖（一等奖）计 10 分，银奖（二等奖）计 8 分，三等奖计 5 分；\n3）市厅级：金奖（一等奖）计 3 分\n2.被中国美术馆、中国国家博物馆、人民大会堂、省级美术馆、博物馆等收藏。\n1）国家级：排名第 1-7 名分别计 20、12、10、8、6、4、2 分/项；\n2）省部级：排名第 1-3 名分别计 5、3、1 分/项。\n3.作品发表期刊（指艺术类、文艺类作品独创或合创第一名在省级以上正式刊物发表）。\n1）核心期刊：4 分/幅；\n2）一般期刊：1 分/幅。', 30, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824963', 46, '科学研究与社会服务', '科研成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计35分，参与排名第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计25分，参与排名第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计15分，参与排名第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与排名第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与排名第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与排名第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分。', 35, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824964', 46, '科学研究与社会服务', '专利、软著等', '获国家发明专利授权：主持计20分/项，参与排名第1名计5分；\n已颁布的国家行业技术标准：主持计5分/项，参与排名第1名计3分；\n获国家实用新型专利授权：主持计3分/项，参与排名第1名计1分；\n获外观设计专利授权或软件著作权等：主持计1分/项', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824965', 46, '科学研究与社会服务', '主持或参与国家级科学研究课题项目', '主持计40分，参与排名第1-5名分别计35分、30分、25分、20分、15分，其余有效排名计8分', 40, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824966', 46, '科学研究与社会服务', '主持或参与省部级A类课题项目', '主持计20分/项，参与排名第1-4名分别计10分、8分、6分、4分，其余有效排名计3分', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824967', 46, '科学研究与社会服务', '主持或参与省部级B类课题项目', '主持计10分/项，参与排名第1-3名分别计5分、3分、2分，其余有效排名计1分；', 10, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824968', 46, '科学研究与社会服务', '主持或参与市厅级课题项目', '主持计5分/项，参与排名第1-2名分别计2分、1分，其余有效排名计0.5分', 5, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824969', 46, '科学研究与社会服务', '主持横向项目', '单项进账经费：小于5万元1分；5-10万元2分；10-20万元4分；20-30万元6分；大于30万元的每增加10万加计1分', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824970', 46, '科学研究与社会服务', '创新研究机构：主持或参与工程技术研究中心、工程研究中心、重点实验室', '主持：省部级计25分，市厅级计10分，校级计3分；\n参与：省部级排名第1-5名分别计10、8、6、4、2分，其他有效名次计1分；\n市厅级排名第1名计5分，其他有效名次计1分', 25, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('504291504118824971', 46, '科学研究与社会服务', '承担国培、技术培训', '教师每担任1次校内外各类国培、省培及技术培训的培训讲师计2分，最高不超过6分', 6, 0, 1, '在校外担任技术培训的需提供盖章证明');
INSERT INTO `sys_task` VALUES ('504291504139796480', 46, '产教融合', '下企业实践', '教师下企业实践（按学校文件规定认定）1个月，计3分；2个月及以上计5分', 5, 0, 1, NULL);
INSERT INTO `sys_task` VALUES ('504291504139796481', 46, '产教融合', '培训', '参加有学院派出的国培、省培及各类技术培训，7天到20天的计3分；超过20天的计5分', 8, 0, 1, '需要获得培训结业证书');
INSERT INTO `sys_task` VALUES ('504291504139796482', 46, '产教融合', '联系企业', '联系、走访1家企业，计2分；联系、走访1家校友企业，计3分；联系、走访1家优质校友企业，计5分；联系、走访1家企业，并实际招聘2名以上毕业生，计8分', 8, 0, 1, '提供走访照片及企业基本信息、座谈等相关材料。优质校友企业指：员工数量大于50人或者年产值大于2000万的企业');
INSERT INTO `sys_task` VALUES ('504291504139796483', 46, '产教融合', '就业工作', '在每年的双选会中，提供1家企业信息，企业实际到校进行招聘，计2分，以此类推', 10, 0, 1, NULL);
INSERT INTO `sys_task` VALUES ('599263473074962432', 47, '个人荣誉', '工作业绩突出，个人获得表彰奖励（项目清单见职称文件附件2）', '国家级计25分，省部级计12分，市厅级计6分，校级A级计3分，校级B级计1分', 25, 0, 1, '不包括附件2中的省教育厅和学校的定期奖励（嘉奖和记功）');
INSERT INTO `sys_task` VALUES ('599263473095933952', 47, '日常教学常规', '上学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 0, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933953', 47, '日常教学常规', '下学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 0, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933954', 47, '日常教学常规', '上学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933955', 47, '日常教学常规', '下学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933956', 47, '日常教学常规', '上学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 0, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933957', 47, '日常教学常规', '下学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 0, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933958', 47, '日常教学常规', '承担综合实训课程任务', '承担1个班的第5学期综合实训(课时数需大于256课时)，计15分', 15, 0, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933959', 47, '日常教学常规', '承担毕业设计、岗位实习的指导任务', '指导15个学生的毕业设计、岗位实习，计5分；指导16-20人，计6分；指导21-25人，计7分；以此类推', 10, 0, 0, '为保证质量，原则上，该项不超过10分。毕业设计成绩通过的学生，相关资料需要完备，及时上传。需通过学院、学校毕业设计检查，以及省教育厅的毕业设计抽查。提供指导的学生班级、姓名等信息作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933960', 47, '日常教学常规', '承担技能抽查课程任务', '承担技能抽查课程任务，课时数大于等于80课时（一个班的技能抽查课程总课时），计5分，其他，计3分', 5, 0, 0, '需要按学院要求，完成校级技能抽查，以及省教育厅的技能抽查。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933961', 47, '日常教学常规', '制订主要教学文件：人才培养方案、课程标准、专业技能考核标准与题库', '主持制定人才培养方案计3分，参与制定计1分；主持制定课程标准计2分，修订课程标准计1分；参与修订专业技能考核标准与题库计1分', 8, 0, 1, '本次认定23级人才培养方案的制订工作，其他工作量暂不认定。今后在认定时，以通过专家论证为准。人才培养方案的制定，提供教研室主任签字的认定名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933962', 47, '日常教学常规', '公开课', '承担院级公开课，计2分；承担校级公开课，计3分', 5, 0, 0, '需要按学院要求，将公开课材料上传至网盘。提供公开课照片及简要说明（学期、授课班级等）作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933963', 47, '日常教学常规', '教师出勤', '每学期周三下午的集中学习，满勤计4分，共计8分。每缺勤1次，扣除0.5分', 8, 0, 0, '因私调整学习时间每学期不超过3次，每超过1次，扣除0.5分。提供教学部下发的考勤数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933964', 47, '日常教学常规', '学生评教', '每学期，学生评教排名学院前30%计10分；排名31%-70%计5分', 20, 0, 0, '提供教学部下发的评教数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('599263473095933965', 47, '日常教学常规', '组织院级各类竞赛', '每组织、策划一场学院竞赛活动，计2分', 4, 0, 0, '针对软件学院全体学生开展各类技能竞赛活动，以赛促学，如Web前端开发大赛、信息安全知识竞赛等，需提交竞赛策划、组织实施等方案，报学院同意，组织学生竞赛');
INSERT INTO `sys_task` VALUES ('599263473095933966', 47, '日常教学常规', '任教研室主任', '担任教研室主任，每学期计5分', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('599263473121099776', 47, '教育教学改革', '课程认证', '合格课认证计1分/1门；优质课认证计5分/1门；金课认证计10分/1门', 10, 0, 0, '以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('599263473121099777', 47, '教育教学改革', '职业教育重点项目建设、资源建设、教学团队建设（项目清单见附件4）', '主持：国家级计35分，省部级计25分，市厅级计10分，校级计5分；\n参与：国家级排名1-5名依次计20、18、16、14、12分，其他名次计5分；\n      省部级排名1-3名依次计8、6、4分，其他名次计2分；\n      市厅级排名第1名计5分，其他名次计1分', 35, 0, 1, '省级及以上项目，可连续两年计分，第一年计100%，第二年计60%。以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('599263473121099778', 47, '教育教学改革', '教材建设', '国家级规划教材：主编（排名第1）计20分/本；主编（其他名次）计15分/本；副主编计8分/本；参编计5分/本；\n省级教材：主编（排名第1）计15分/本；主编（其他名次）计10分/本；副主编计7分/本；参编计5分/本；\n其他教材：主编计5分/本；副主编计3分/本；参编计1分/本', 20, 0, 1, '1.国家级教材包括“十四五”职业教育国家规划教材、职业教育国家级优质教材、全国优秀教材奖等。2.省级教材包括省级职业教育优质教材等。3.要求学校为第一主编单位。4.可连续两年计分，第一年计100%，第二年计60%');
INSERT INTO `sys_task` VALUES ('599263473121099779', 47, '教育教学改革', '教学成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计40分，参与第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计30分，参与第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计20分，参与第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分', 40, 0, 1, '获省级及以上教学成果奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准');
INSERT INTO `sys_task` VALUES ('599263473121099780', 47, '教育教学改革', '教师职业能力竞赛', '国家级：一等奖计50分；二等奖计40分；三等奖计30分；\n省级：一等奖计20分；二等奖计15分；三等奖计10分；\n校级：一等奖计8分；二等奖计6分；三等奖计4分；\n院级：所有参与者计2分；', 50, 0, 0, '获省级及以上教师职业能力竞赛获奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准。根据实际备赛情况，每个团队允许提交不超过总人数50%的名额（在备赛团队中又不在获奖名单中的教师），计2分，以团队负责人提交的名单为准');
INSERT INTO `sys_task` VALUES ('599263473121099781', 47, '教育教学改革', '指导学生参加竞赛获奖（奖项清单见附件6）', '国家级：一等奖第1指导老师计35分，其他指导老师计28分；\n二等奖第1指导老师计24分，其他指导老师计20分；\n三等奖第1指导老师计16分，其他指导老师计12分；\n省部级A类：一等奖第1指导老师计15分、其他指导老师计12分；\n二等奖第1指导老师计9分、其他指导老师计7分；\n三等奖第1指导老师计5分、其他指导老师计4分；\n省部级B类：一等奖第1指导老师计12分、其他指导老师计10分；\n二等奖第1指导老师计7分、其他指导老师计5分；\n三等奖第1指导老师计4分、其他指导老师计3分；\n市厅级一等奖第一指导老师计2分，其他指导老师计1分；院级及其他等次奖项计1分；', 35, 0, 1, '该项不累计计分，以最高项计分为准。教师指导学生参加省教育厅、国家教育部主办的职业院校技能大赛，以团队提交的技能竞赛集训方案中指导团队教师名单为依据，每位教师（在备赛团队中又不在获奖名单中的教师）计2分');
INSERT INTO `sys_task` VALUES ('599263473121099782', 47, '教育教学改革', '毕业设计抽查', '全省同类项目排名前3的，专业负责人加10分，指导团队成员加5分（抽查专业负责人及当年团队指导老师由各学院认定、教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('599263473121099783', 47, '教育教学改革', '优秀人才培养方案和新专业合格性评估', '专业人才培养方案获优秀等级或新设专业办学水平合格性评价验收通过的，专业负责人加10分，指导团队成员加5分（当年团队指导老师由各学院认定，教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('599263473150459904', 47, '科学研究与社会服务', '独立或以第一作者（或通信作者）发表本专业学术论文/教研教改论文/思政教育论文', '发表SCI、SSCI、EI源刊论文或论文被《中国科学》《新华文摘》《中国社会科学文摘》全文转载20分/篇；\n发表CSSCI、CSCD核心库来源期刊论文，计12分/篇；\n发表北大核心期刊论文8分/篇；\n一般期刊：本科院校学报2分/篇；\n一般期刊：一般省级期刊1分/篇', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459905', 47, '科学研究与社会服务', '著作和译著', '独著计16分/本，第一作者计12分/本，第二作者计4分/本\n独译计4分/本，合译第一作者3分/本，第二作者计1分/本', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459906', 47, '科学研究与社会服务', '原创作品、产品', '1.美术类和表演类作品或工艺类作品获奖（参加市厅级及以上政府主管部门主办的各类展览、竞赛并获得表彰奖励，级别以证书盖章或主办部门公章为准）。\n1）国家级：金奖（特等奖、一等奖）计 30 分，银奖（二等奖）计 20 分，铜奖（三等奖）计 10 分；\n2）省部级：金奖（一等奖）计 10 分，银奖（二等奖）计 8 分，三等奖计 5 分；\n3）市厅级：金奖（一等奖）计 3 分\n2.被中国美术馆、中国国家博物馆、人民大会堂、省级美术馆、博物馆等收藏。\n1）国家级：排名第 1-7 名分别计 20、12、10、8、6、4、2 分/项；\n2）省部级：排名第 1-3 名分别计 5、3、1 分/项。\n3.作品发表期刊（指艺术类、文艺类作品独创或合创第一名在省级以上正式刊物发表）。\n1）核心期刊：4 分/幅；\n2）一般期刊：1 分/幅。', 30, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459907', 47, '科学研究与社会服务', '科研成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计35分，参与排名第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计25分，参与排名第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计15分，参与排名第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与排名第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与排名第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与排名第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分。', 35, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459908', 47, '科学研究与社会服务', '专利、软著等', '获国家发明专利授权：主持计20分/项，参与排名第1名计5分；\n已颁布的国家行业技术标准：主持计5分/项，参与排名第1名计3分；\n获国家实用新型专利授权：主持计3分/项，参与排名第1名计1分；\n获外观设计专利授权或软件著作权等：主持计1分/项', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459909', 47, '科学研究与社会服务', '主持或参与国家级科学研究课题项目', '主持计40分，参与排名第1-5名分别计35分、30分、25分、20分、15分，其余有效排名计8分', 40, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459910', 47, '科学研究与社会服务', '主持或参与省部级A类课题项目', '主持计20分/项，参与排名第1-4名分别计10分、8分、6分、4分，其余有效排名计3分', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459911', 47, '科学研究与社会服务', '主持或参与省部级B类课题项目', '主持计10分/项，参与排名第1-3名分别计5分、3分、2分，其余有效排名计1分；', 10, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459912', 47, '科学研究与社会服务', '主持或参与市厅级课题项目', '主持计5分/项，参与排名第1-2名分别计2分、1分，其余有效排名计0.5分', 5, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459913', 47, '科学研究与社会服务', '主持横向项目', '单项进账经费：小于5万元1分；5-10万元2分；10-20万元4分；20-30万元6分；大于30万元的每增加10万加计1分', 20, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459914', 47, '科学研究与社会服务', '创新研究机构：主持或参与工程技术研究中心、工程研究中心、重点实验室', '主持：省部级计25分，市厅级计10分，校级计3分；\n参与：省部级排名第1-5名分别计10、8、6、4、2分，其他有效名次计1分；\n市厅级排名第1名计5分，其他有效名次计1分', 25, 0, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('599263473150459915', 47, '科学研究与社会服务', '承担国培、技术培训', '教师每担任1次校内外各类国培、省培及技术培训的培训讲师计2分，最高不超过6分', 6, 0, 1, '在校外担任技术培训的需提供盖章证明');
INSERT INTO `sys_task` VALUES ('599263473171431424', 47, '产教融合', '下企业实践', '教师下企业实践（按学校文件规定认定）1个月，计3分；2个月及以上计5分', 5, 0, 1, NULL);
INSERT INTO `sys_task` VALUES ('599263473171431425', 47, '产教融合', '培训', '参加有学院派出的国培、省培及各类技术培训，7天到20天的计3分；超过20天的计5分', 8, 0, 1, '需要获得培训结业证书');
INSERT INTO `sys_task` VALUES ('599263473171431426', 47, '产教融合', '联系企业', '联系、走访1家企业，计2分；联系、走访1家校友企业，计3分；联系、走访1家优质校友企业，计5分；联系、走访1家企业，并实际招聘2名以上毕业生，计8分', 8, 0, 1, '提供走访照片及企业基本信息、座谈等相关材料。优质校友企业指：员工数量大于50人或者年产值大于2000万的企业');
INSERT INTO `sys_task` VALUES ('599263473171431427', 47, '产教融合', '就业工作', '在每年的双选会中，提供1家企业信息，企业实际到校进行招聘，计2分，以此类推', 10, 0, 1, NULL);
INSERT INTO `sys_task` VALUES ('626196232674476032', 48, '个人荣誉', '工作业绩突出，个人获得表彰奖励（项目清单见职称文件附件2）', '国家级计25分，省部级计12分，市厅级计6分，校级A级计3分，校级B级计1分', 25, 1, 1, '不包括附件2中的省教育厅和学校的定期奖励（嘉奖和记功）');
INSERT INTO `sys_task` VALUES ('626196232712224768', 48, '日常教学常规', '上学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 1, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224769', 48, '日常教学常规', '下学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 1, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224770', 48, '日常教学常规', '上学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224771', 48, '日常教学常规', '下学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224772', 48, '日常教学常规', '上学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 1, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224773', 48, '日常教学常规', '下学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 1, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224774', 48, '日常教学常规', '承担综合实训课程任务', '承担1个班的第5学期综合实训(课时数需大于256课时)，计15分', 15, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224775', 48, '日常教学常规', '承担毕业设计、岗位实习的指导任务', '指导15个学生的毕业设计、岗位实习，计5分；指导16-20人，计6分；指导21-25人，计7分；以此类推', 10, 1, 0, '为保证质量，原则上，该项不超过10分。毕业设计成绩通过的学生，相关资料需要完备，及时上传。需通过学院、学校毕业设计检查，以及省教育厅的毕业设计抽查。提供指导的学生班级、姓名等信息作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224776', 48, '日常教学常规', '承担技能抽查课程任务', '承担技能抽查课程任务，课时数大于等于80课时（一个班的技能抽查课程总课时），计5分，其他，计3分', 5, 1, 0, '需要按学院要求，完成校级技能抽查，以及省教育厅的技能抽查。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224777', 48, '日常教学常规', '制订主要教学文件：人才培养方案、课程标准、专业技能考核标准与题库', '主持制定人才培养方案计3分，参与制定计1分；主持制定课程标准计2分，修订课程标准计1分；参与修订专业技能考核标准与题库计1分', 8, 1, 1, '本次认定23级人才培养方案的制订工作，其他工作量暂不认定。今后在认定时，以通过专家论证为准。人才培养方案的制定，提供教研室主任签字的认定名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224778', 48, '日常教学常规', '公开课', '承担院级公开课，计2分；承担校级公开课，计3分', 5, 1, 0, '需要按学院要求，将公开课材料上传至网盘。提供公开课照片及简要说明（学期、授课班级等）作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224779', 48, '日常教学常规', '教师出勤', '每学期周三下午的集中学习，满勤计4分，共计8分。每缺勤1次，扣除0.5分', 8, 0, 0, '因私调整学习时间每学期不超过3次，每超过1次，扣除0.5分。提供教学部下发的考勤数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224780', 48, '日常教学常规', '学生评教', '每学期，学生评教排名学院前30%计10分；排名31%-70%计5分', 20, 1, 0, '提供教学部下发的评教数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('626196232712224781', 48, '日常教学常规', '组织院级各类竞赛', '每组织、策划一场学院竞赛活动，计2分', 4, 1, 0, '针对软件学院全体学生开展各类技能竞赛活动，以赛促学，如Web前端开发大赛、信息安全知识竞赛等，需提交竞赛策划、组织实施等方案，报学院同意，组织学生竞赛');
INSERT INTO `sys_task` VALUES ('626196232712224782', 48, '日常教学常规', '任教研室主任', '担任教研室主任，每学期计5分', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('626196232766750720', 48, '教育教学改革', '课程认证', '合格课认证计1分/1门；优质课认证计5分/1门；金课认证计10分/1门', 10, 1, 0, '以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('626196232766750721', 48, '教育教学改革', '职业教育重点项目建设、资源建设、教学团队建设（项目清单见附件4）', '主持：国家级计35分，省部级计25分，市厅级计10分，校级计5分；\n参与：国家级排名1-5名依次计20、18、16、14、12分，其他名次计5分；\n      省部级排名1-3名依次计8、6、4分，其他名次计2分；\n      市厅级排名第1名计5分，其他名次计1分', 35, 1, 1, '省级及以上项目，可连续两年计分，第一年计100%，第二年计60%。以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('626196232766750722', 48, '教育教学改革', '教材建设', '国家级规划教材：主编（排名第1）计20分/本；主编（其他名次）计15分/本；副主编计8分/本；参编计5分/本；\n省级教材：主编（排名第1）计15分/本；主编（其他名次）计10分/本；副主编计7分/本；参编计5分/本；\n其他教材：主编计5分/本；副主编计3分/本；参编计1分/本', 20, 1, 1, '1.国家级教材包括“十四五”职业教育国家规划教材、职业教育国家级优质教材、全国优秀教材奖等。2.省级教材包括省级职业教育优质教材等。3.要求学校为第一主编单位。4.可连续两年计分，第一年计100%，第二年计60%');
INSERT INTO `sys_task` VALUES ('626196232766750723', 48, '教育教学改革', '教学成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计40分，参与第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计30分，参与第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计20分，参与第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分', 40, 1, 1, '获省级及以上教学成果奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准');
INSERT INTO `sys_task` VALUES ('626196232766750724', 48, '教育教学改革', '教师职业能力竞赛', '国家级：一等奖计50分；二等奖计40分；三等奖计30分；\n省级：一等奖计20分；二等奖计15分；三等奖计10分；\n校级：一等奖计8分；二等奖计6分；三等奖计4分；\n院级：所有参与者计2分；', 50, 1, 0, '获省级及以上教师职业能力竞赛获奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准。根据实际备赛情况，每个团队允许提交不超过总人数50%的名额（在备赛团队中又不在获奖名单中的教师），计2分，以团队负责人提交的名单为准');
INSERT INTO `sys_task` VALUES ('626196232766750725', 48, '教育教学改革', '指导学生参加竞赛获奖（奖项清单见附件6）', '国家级：一等奖第1指导老师计35分，其他指导老师计28分；\n二等奖第1指导老师计24分，其他指导老师计20分；\n三等奖第1指导老师计16分，其他指导老师计12分；\n省部级A类：一等奖第1指导老师计15分、其他指导老师计12分；\n二等奖第1指导老师计9分、其他指导老师计7分；\n三等奖第1指导老师计5分、其他指导老师计4分；\n省部级B类：一等奖第1指导老师计12分、其他指导老师计10分；\n二等奖第1指导老师计7分、其他指导老师计5分；\n三等奖第1指导老师计4分、其他指导老师计3分；\n市厅级一等奖第一指导老师计2分，其他指导老师计1分；院级及其他等次奖项计1分；', 35, 1, 1, '该项不累计计分，以最高项计分为准。教师指导学生参加省教育厅、国家教育部主办的职业院校技能大赛，以团队提交的技能竞赛集训方案中指导团队教师名单为依据，每位教师（在备赛团队中又不在获奖名单中的教师）计2分');
INSERT INTO `sys_task` VALUES ('626196232766750726', 48, '教育教学改革', '毕业设计抽查', '全省同类项目排名前3的，专业负责人加10分，指导团队成员加5分（抽查专业负责人及当年团队指导老师由各学院认定、教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('626196232766750727', 48, '教育教学改革', '优秀人才培养方案和新专业合格性评估', '专业人才培养方案获优秀等级或新设专业办学水平合格性评价验收通过的，专业负责人加10分，指导团队成员加5分（当年团队指导老师由各学院认定，教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('626196232796110848', 48, '科学研究与社会服务', '独立或以第一作者（或通信作者）发表本专业学术论文/教研教改论文/思政教育论文', '发表SCI、SSCI、EI源刊论文或论文被《中国科学》《新华文摘》《中国社会科学文摘》全文转载20分/篇；\n发表CSSCI、CSCD核心库来源期刊论文，计12分/篇；\n发表北大核心期刊论文8分/篇；\n一般期刊：本科院校学报2分/篇；\n一般期刊：一般省级期刊1分/篇', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110849', 48, '科学研究与社会服务', '著作和译著', '独著计16分/本，第一作者计12分/本，第二作者计4分/本\n独译计4分/本，合译第一作者3分/本，第二作者计1分/本', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110850', 48, '科学研究与社会服务', '原创作品、产品', '1.美术类和表演类作品或工艺类作品获奖（参加市厅级及以上政府主管部门主办的各类展览、竞赛并获得表彰奖励，级别以证书盖章或主办部门公章为准）。\n1）国家级：金奖（特等奖、一等奖）计 30 分，银奖（二等奖）计 20 分，铜奖（三等奖）计 10 分；\n2）省部级：金奖（一等奖）计 10 分，银奖（二等奖）计 8 分，三等奖计 5 分；\n3）市厅级：金奖（一等奖）计 3 分\n2.被中国美术馆、中国国家博物馆、人民大会堂、省级美术馆、博物馆等收藏。\n1）国家级：排名第 1-7 名分别计 20、12、10、8、6、4、2 分/项；\n2）省部级：排名第 1-3 名分别计 5、3、1 分/项。\n3.作品发表期刊（指艺术类、文艺类作品独创或合创第一名在省级以上正式刊物发表）。\n1）核心期刊：4 分/幅；\n2）一般期刊：1 分/幅。', 30, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110851', 48, '科学研究与社会服务', '科研成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计35分，参与排名第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计25分，参与排名第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计15分，参与排名第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与排名第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与排名第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与排名第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分。', 35, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110852', 48, '科学研究与社会服务', '专利、软著等', '获国家发明专利授权：主持计20分/项，参与排名第1名计5分；\n已颁布的国家行业技术标准：主持计5分/项，参与排名第1名计3分；\n获国家实用新型专利授权：主持计3分/项，参与排名第1名计1分；\n获外观设计专利授权或软件著作权等：主持计1分/项', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110853', 48, '科学研究与社会服务', '主持或参与国家级科学研究课题项目', '主持计40分，参与排名第1-5名分别计35分、30分、25分、20分、15分，其余有效排名计8分', 40, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110854', 48, '科学研究与社会服务', '主持或参与省部级A类课题项目', '主持计20分/项，参与排名第1-4名分别计10分、8分、6分、4分，其余有效排名计3分', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110855', 48, '科学研究与社会服务', '主持或参与省部级B类课题项目', '主持计10分/项，参与排名第1-3名分别计5分、3分、2分，其余有效排名计1分；', 10, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110856', 48, '科学研究与社会服务', '主持或参与市厅级课题项目', '主持计5分/项，参与排名第1-2名分别计2分、1分，其余有效排名计0.5分', 5, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110857', 48, '科学研究与社会服务', '主持横向项目', '单项进账经费：小于5万元1分；5-10万元2分；10-20万元4分；20-30万元6分；大于30万元的每增加10万加计1分', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110858', 48, '科学研究与社会服务', '创新研究机构：主持或参与工程技术研究中心、工程研究中心、重点实验室', '主持：省部级计25分，市厅级计10分，校级计3分；\n参与：省部级排名第1-5名分别计10、8、6、4、2分，其他有效名次计1分；\n市厅级排名第1名计5分，其他有效名次计1分', 25, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('626196232796110859', 48, '科学研究与社会服务', '承担国培、技术培训', '教师每担任1次校内外各类国培、省培及技术培训的培训讲师计2分，最高不超过6分', 6, 1, 1, '在校外担任技术培训的需提供盖章证明');
INSERT INTO `sys_task` VALUES ('626196232829665280', 48, '产教融合', '下企业实践', '教师下企业实践（按学校文件规定认定）1个月，计3分；2个月及以上计5分', 5, 1, 1, NULL);
INSERT INTO `sys_task` VALUES ('626196232829665281', 48, '产教融合', '培训', '参加有学院派出的国培、省培及各类技术培训，7天到20天的计3分；超过20天的计5分', 8, 1, 1, '需要获得培训结业证书');
INSERT INTO `sys_task` VALUES ('626196232829665282', 48, '产教融合', '联系企业', '联系、走访1家企业，计2分；联系、走访1家校友企业，计3分；联系、走访1家优质校友企业，计5分；联系、走访1家企业，并实际招聘2名以上毕业生，计8分', 8, 1, 1, '提供走访照片及企业基本信息、座谈等相关材料。优质校友企业指：员工数量大于50人或者年产值大于2000万的企业');
INSERT INTO `sys_task` VALUES ('626196232829665283', 48, '产教融合', '就业工作', '在每年的双选会中，提供1家企业信息，企业实际到校进行招聘，计2分，以此类推', 10, 1, 1, NULL);
INSERT INTO `sys_task` VALUES ('766437421830111232', 49, '个人荣誉', '工作业绩突出，个人获得表彰奖励（项目清单见职称文件附件2）', '国家级计25分，省部级计12分，市厅级计6分，校级A级计3分，校级B级计1分', 25, 1, 1, '不包括附件2中的省教育厅和学校的定期奖励（嘉奖和记功）');
INSERT INTO `sys_task` VALUES ('766437421859471360', 49, '日常教学常规', '上学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 1, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471361', 49, '日常教学常规', '下学期承担理实一体课程授课任务', '课时总数超过256课时，计10分；课时总数超过192课时，计5分', 10, 1, 0, '该项指课表中除学期末实训、综合实训、毕业设计、岗位实习以外的课时，且不乘以人数系数的原始课时。参加教师职业能力竞赛获省级以上奖励，视同完成任务，计10分（教师可选择上学期或者下学期进行计分，不累计）。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471362', 49, '日常教学常规', '上学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471363', 49, '日常教学常规', '下学期承担期末实训任务', '承担1个班的期末实训任务（40课时），计3分，以此类推', 6, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471364', 49, '日常教学常规', '上学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 1, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471365', 49, '日常教学常规', '下学期承担新课、难课授课任务', '承担1门新课或难课授课任务，计3分，以此类推', 9, 1, 0, '各教研室讨论22级、23级的人才培养方案，确定新课、难课，原则上每级人才培养方案中不超过5门，经教研室全体教师同意后，报教学工作部备案。从2024级开始，在提交人才培养方案时，同步提交新课、难课名单。如果对比前3年人才培养方案，课程名称发生变化，而课程内容没有发生较大变化，原则上不应认定为新课。提供教研室全体教师签字通过的认定课程名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471366', 49, '日常教学常规', '承担综合实训课程任务', '承担1个班的第5学期综合实训(课时数需大于256课时)，计15分', 15, 1, 0, '需要按学院要求，提交完整的实训资料，包括实训案例实施方案、实训指导书、实训案例工程文件及素材、实训案例演示及讲解视频。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471367', 49, '日常教学常规', '承担毕业设计、岗位实习的指导任务', '指导15个学生的毕业设计、岗位实习，计5分；指导16-20人，计6分；指导21-25人，计7分；以此类推', 10, 1, 0, '为保证质量，原则上，该项不超过10分。毕业设计成绩通过的学生，相关资料需要完备，及时上传。需通过学院、学校毕业设计检查，以及省教育厅的毕业设计抽查。提供指导的学生班级、姓名等信息作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471368', 49, '日常教学常规', '承担技能抽查课程任务', '承担技能抽查课程任务，课时数大于等于80课时（一个班的技能抽查课程总课时），计5分，其他，计3分', 5, 1, 0, '需要按学院要求，完成校级技能抽查，以及省教育厅的技能抽查。提供教务系统课表截图作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471369', 49, '日常教学常规', '制订主要教学文件：人才培养方案、课程标准、专业技能考核标准与题库', '主持制定人才培养方案计3分，参与制定计1分；主持制定课程标准计2分，修订课程标准计1分；参与修订专业技能考核标准与题库计1分', 8, 1, 1, '本次认定23级人才培养方案的制订工作，其他工作量暂不认定。今后在认定时，以通过专家论证为准。人才培养方案的制定，提供教研室主任签字的认定名单作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471370', 49, '日常教学常规', '公开课', '承担院级公开课，计2分；承担校级公开课，计3分', 5, 1, 0, '需要按学院要求，将公开课材料上传至网盘。提供公开课照片及简要说明（学期、授课班级等）作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471371', 49, '日常教学常规', '教师出勤', '每学期周三下午的集中学习，满勤计4分，共计8分。每缺勤1次，扣除0.5分', 8, 0, 0, '因私调整学习时间每学期不超过3次，每超过1次，扣除0.5分。提供教学部下发的考勤数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471372', 49, '日常教学常规', '学生评教', '每学期，学生评教排名学院前30%计10分；排名31%-70%计5分', 20, 1, 0, '提供教学部下发的评教数据作为佐证材料');
INSERT INTO `sys_task` VALUES ('766437421859471373', 49, '日常教学常规', '组织院级各类竞赛', '每组织、策划一场学院竞赛活动，计2分', 4, 1, 0, '针对软件学院全体学生开展各类技能竞赛活动，以赛促学，如Web前端开发大赛、信息安全知识竞赛等，需提交竞赛策划、组织实施等方案，报学院同意，组织学生竞赛');
INSERT INTO `sys_task` VALUES ('766437421859471374', 49, '日常教学常规', '任教研室主任', '担任教研室主任，每学期计5分', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('766437421884637184', 49, '教育教学改革', '课程认证', '合格课认证计1分/1门；优质课认证计5分/1门；金课认证计10分/1门', 10, 1, 0, '以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('766437421884637185', 49, '教育教学改革', '职业教育重点项目建设、资源建设、教学团队建设（项目清单见附件4）', '主持：国家级计35分，省部级计25分，市厅级计10分，校级计5分；\n参与：国家级排名1-5名依次计20、18、16、14、12分，其他名次计5分；\n      省部级排名1-3名依次计8、6、4分，其他名次计2分；\n      市厅级排名第1名计5分，其他名次计1分', 35, 1, 1, '省级及以上项目，可连续两年计分，第一年计100%，第二年计60%。以教务处当年的认定结果为依据');
INSERT INTO `sys_task` VALUES ('766437421884637186', 49, '教育教学改革', '教材建设', '国家级规划教材：主编（排名第1）计20分/本；主编（其他名次）计15分/本；副主编计8分/本；参编计5分/本；\n省级教材：主编（排名第1）计15分/本；主编（其他名次）计10分/本；副主编计7分/本；参编计5分/本；\n其他教材：主编计5分/本；副主编计3分/本；参编计1分/本', 20, 1, 1, '1.国家级教材包括“十四五”职业教育国家规划教材、职业教育国家级优质教材、全国优秀教材奖等。2.省级教材包括省级职业教育优质教材等。3.要求学校为第一主编单位。4.可连续两年计分，第一年计100%，第二年计60%');
INSERT INTO `sys_task` VALUES ('766437421884637187', 49, '教育教学改革', '教学成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计40分，参与第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计30分，参与第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计20分，参与第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分', 40, 1, 1, '获省级及以上教学成果奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准');
INSERT INTO `sys_task` VALUES ('766437421884637188', 49, '教育教学改革', '教师职业能力竞赛', '国家级：一等奖计50分；二等奖计40分；三等奖计30分；\n省级：一等奖计20分；二等奖计15分；三等奖计10分；\n校级：一等奖计8分；二等奖计6分；三等奖计4分；\n院级：所有参与者计2分；', 50, 1, 0, '获省级及以上教师职业能力竞赛获奖，可连续两年计分，第一年计100%，第二年计60%。该项不累计计分，以最高项计分为准。根据实际备赛情况，每个团队允许提交不超过总人数50%的名额（在备赛团队中又不在获奖名单中的教师），计2分，以团队负责人提交的名单为准');
INSERT INTO `sys_task` VALUES ('766437421884637189', 49, '教育教学改革', '指导学生参加竞赛获奖（奖项清单见附件6）', '国家级：一等奖第1指导老师计35分，其他指导老师计28分；\n二等奖第1指导老师计24分，其他指导老师计20分；\n三等奖第1指导老师计16分，其他指导老师计12分；\n省部级A类：一等奖第1指导老师计15分、其他指导老师计12分；\n二等奖第1指导老师计9分、其他指导老师计7分；\n三等奖第1指导老师计5分、其他指导老师计4分；\n省部级B类：一等奖第1指导老师计12分、其他指导老师计10分；\n二等奖第1指导老师计7分、其他指导老师计5分；\n三等奖第1指导老师计4分、其他指导老师计3分；\n市厅级一等奖第一指导老师计2分，其他指导老师计1分；院级及其他等次奖项计1分；', 35, 1, 1, '该项不累计计分，以最高项计分为准。教师指导学生参加省教育厅、国家教育部主办的职业院校技能大赛，以团队提交的技能竞赛集训方案中指导团队教师名单为依据，每位教师（在备赛团队中又不在获奖名单中的教师）计2分');
INSERT INTO `sys_task` VALUES ('766437421884637190', 49, '教育教学改革', '毕业设计抽查', '全省同类项目排名前3的，专业负责人加10分，指导团队成员加5分（抽查专业负责人及当年团队指导老师由各学院认定、教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('766437421884637191', 49, '教育教学改革', '优秀人才培养方案和新专业合格性评估', '专业人才培养方案获优秀等级或新设专业办学水平合格性评价验收通过的，专业负责人加10分，指导团队成员加5分（当年团队指导老师由各学院认定，教务处审核）', 10, 0, 0, NULL);
INSERT INTO `sys_task` VALUES ('766437421926580224', 49, '科学研究与社会服务', '独立或以第一作者（或通信作者）发表本专业学术论文/教研教改论文/思政教育论文', '发表SCI、SSCI、EI源刊论文或论文被《中国科学》《新华文摘》《中国社会科学文摘》全文转载20分/篇；\n发表CSSCI、CSCD核心库来源期刊论文，计12分/篇；\n发表北大核心期刊论文8分/篇；\n一般期刊：本科院校学报2分/篇；\n一般期刊：一般省级期刊1分/篇', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580225', 49, '科学研究与社会服务', '著作和译著', '独著计16分/本，第一作者计12分/本，第二作者计4分/本\n独译计4分/本，合译第一作者3分/本，第二作者计1分/本', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580226', 49, '科学研究与社会服务', '原创作品、产品', '1.美术类和表演类作品或工艺类作品获奖（参加市厅级及以上政府主管部门主办的各类展览、竞赛并获得表彰奖励，级别以证书盖章或主办部门公章为准）。\n1）国家级：金奖（特等奖、一等奖）计 30 分，银奖（二等奖）计 20 分，铜奖（三等奖）计 10 分；\n2）省部级：金奖（一等奖）计 10 分，银奖（二等奖）计 8 分，三等奖计 5 分；\n3）市厅级：金奖（一等奖）计 3 分\n2.被中国美术馆、中国国家博物馆、人民大会堂、省级美术馆、博物馆等收藏。\n1）国家级：排名第 1-7 名分别计 20、12、10、8、6、4、2 分/项；\n2）省部级：排名第 1-3 名分别计 5、3、1 分/项。\n3.作品发表期刊（指艺术类、文艺类作品独创或合创第一名在省级以上正式刊物发表）。\n1）核心期刊：4 分/幅；\n2）一般期刊：1 分/幅。', 30, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580227', 49, '科学研究与社会服务', '科研成果奖', '1.国家级：\n一等奖：主持人及参与排名前3计35分，参与排名第4名计25分，第5-7名计15分，其他有效名次计10分；\n二等奖：主持人及参与排名第1计25分，参与排名第2-4名计15分，第5-7名计10分，其他有效名次计5分；\n2.省部级：\n特等奖：主持人及参与排名第1计15分，参与排名第2-4名计12分，第5-7名计8分，其他有效名次计6分；\n一等奖：主持人及参与排名第1计10分，参与排名第2-4名计8分，第5-7名计6分；其他有效名次计4分；\n二等奖：主持人及参与排名第1计12分，参与排名第2-4名计6分，其他有效名次计4分；\n三等奖：主持人及参与排名第1计8分，参与排名第2-4名计4分，其他有效名次计2分；\n3.市厅级：一等奖主持计2分，有效名次计0.5分；\n4.校级：一等奖主持计1分。', 35, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580228', 49, '科学研究与社会服务', '专利、软著等', '获国家发明专利授权：主持计20分/项，参与排名第1名计5分；\n已颁布的国家行业技术标准：主持计5分/项，参与排名第1名计3分；\n获国家实用新型专利授权：主持计3分/项，参与排名第1名计1分；\n获外观设计专利授权或软件著作权等：主持计1分/项', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580229', 49, '科学研究与社会服务', '主持或参与国家级科学研究课题项目', '主持计40分，参与排名第1-5名分别计35分、30分、25分、20分、15分，其余有效排名计8分', 40, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580230', 49, '科学研究与社会服务', '主持或参与省部级A类课题项目', '主持计20分/项，参与排名第1-4名分别计10分、8分、6分、4分，其余有效排名计3分', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580231', 49, '科学研究与社会服务', '主持或参与省部级B类课题项目', '主持计10分/项，参与排名第1-3名分别计5分、3分、2分，其余有效排名计1分；', 10, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580232', 49, '科学研究与社会服务', '主持或参与市厅级课题项目', '主持计5分/项，参与排名第1-2名分别计2分、1分，其余有效排名计0.5分', 5, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580233', 49, '科学研究与社会服务', '主持横向项目', '单项进账经费：小于5万元1分；5-10万元2分；10-20万元4分；20-30万元6分；大于30万元的每增加10万加计1分', 20, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580234', 49, '科学研究与社会服务', '创新研究机构：主持或参与工程技术研究中心、工程研究中心、重点实验室', '主持：省部级计25分，市厅级计10分，校级计3分；\n参与：省部级排名第1-5名分别计10、8、6、4、2分，其他有效名次计1分；\n市厅级排名第1名计5分，其他有效名次计1分', 25, 1, 1, '以科研和社会服务处当年认定结果为准');
INSERT INTO `sys_task` VALUES ('766437421926580235', 49, '科学研究与社会服务', '承担国培、技术培训', '教师每担任1次校内外各类国培、省培及技术培训的培训讲师计2分，最高不超过6分', 6, 1, 1, '在校外担任技术培训的需提供盖章证明');
INSERT INTO `sys_task` VALUES ('766437421955940352', 49, '产教融合', '下企业实践', '教师下企业实践（按学校文件规定认定）1个月，计3分；2个月及以上计5分', 5, 1, 1, NULL);
INSERT INTO `sys_task` VALUES ('766437421955940353', 49, '产教融合', '培训', '参加有学院派出的国培、省培及各类技术培训，7天到20天的计3分；超过20天的计5分', 8, 1, 1, '需要获得培训结业证书');
INSERT INTO `sys_task` VALUES ('766437421955940354', 49, '产教融合', '联系企业', '联系、走访1家企业，计2分；联系、走访1家校友企业，计3分；联系、走访1家优质校友企业，计5分；联系、走访1家企业，并实际招聘2名以上毕业生，计8分', 8, 1, 1, '提供走访照片及企业基本信息、座谈等相关材料。优质校友企业指：员工数量大于50人或者年产值大于2000万的企业');
INSERT INTO `sys_task` VALUES ('766437421955940355', 49, '产教融合', '就业工作', '在每年的双选会中，提供1家企业信息，企业实际到校进行招聘，计2分，以此类推', 10, 1, 1, NULL);
